Method.Source:
    /// <summary>
    /// MPJ_18045_Vendor transactions
    /// </summary>
    /// <param name = "metVendTrans">
    /// get the table buffer of vendTrans
    /// </param>
    /// <returns>
    /// return payment note related to the vendor transaction
    /// </returns>
    static display PaymNote metPaymentNotes(VendTrans metVendTrans)
    {
        LedgerJournalTrans  ledgerJournalTrans;
        PaymNote            paymentNote;

        select firstonly PaymentNotes, Invoice from ledgerJournalTrans
            where ledgerJournalTrans.Invoice == metVendTrans.Invoice;
         
        if(ledgerJournalTrans.PaymentNotes)
        {
            paymentNote = ledgerJournalTrans.PaymentNotes;
        }
        
        return paymentNote;

    }
